import sys; sys.path.insert(0, "/workspace")
from netsim.net import Mininet
from netsim.node import Switch
from netsim.topo import Topo
from netsim.utils import generate_ip

# --- minimal stand-ins for the spec'd classes -------------------------------
class Table:
    def __init__(self, name, match_fields, max_size=1024):
        self.name, self.match_fields, self.rules = name, list(match_fields), {}
    def key(self, md): return tuple(sorted(md.items()))
    def add_rule(self, md, action, params=None, priority=0):
        self.rules[self.key(md)] = (action, params or {}, priority)
    def size(self): return len(self.rules)

class Counter:
    def __init__(self, name, size): self.name=name; self.pkts=[0]*size; self.byts=[0]*size
    def increment(self, i, b): self.pkts[i]+=1; self.byts[i]+=b
    def total_packets(self): return sum(self.pkts)
    def total_bytes(self): return sum(self.byts)

class P4Switch(Switch):
    def __init__(self, name, program=None, **p):
        Switch.__init__(self, name, **p); self.tables={}
    def add_table(self, t): self.tables[t.name]=t
    @property
    def pipeline_latency_us(self): return 0.5*len(self.tables)

class P4Topology(Topo):
    def build(self, num_switches=2, num_hosts_per_switch=1, **opts):
        last=None
        for i in range(1, num_switches+1):
            sw=self.addSwitch("s%d"%i)
            for j in range(num_hosts_per_switch):
                n=(i-1)*num_hosts_per_switch+j+1
                self.addLink(self.addHost("h%d"%n), sw, **opts)
            if last: self.addLink(last, sw, **opts)
            last=sw

cfg = dict(num_switches=4, num_hosts_per_switch=1, link_bw=1000, link_delay=1.0,
           table_name="ipv4_lpm", match_fields=["dst_ip"])
topo = P4Topology(num_switches=4, num_hosts_per_switch=1, bw=1000, delay=1.0)
net = Mininet(topo=topo, switch=P4Switch); net.start()

# populate: one entry per destination host in every switch table
for sw in net.switches:
    t = Table(cfg["table_name"], cfg["match_fields"])
    sw.add_table(t)
    for h in net.hosts:
        t.add_rule({"dst_ip": h.ip}, "ipv4_forward", {"port": 1})
entries_all  = sum(s.tables[cfg["table_name"]].size() for s in net.switches)

# variant B: skip the locally attached host
tot_b = 0
for i, sw in enumerate(net.switches):
    t = Table("x", ["dst_ip"])
    for j, h in enumerate(net.hosts):
        if i != j: t.add_rule({"dst_ip": h.ip}, "fwd")
    tot_b += t.size()

# variant C: per shortest-path installation, dedup by match key
tabs = {s.name: Table("y", ["dst_ip"]) for s in net.switches}
dup = 0
for a in net.hosts:
    for b in net.hosts:
        if a is b: continue
        for s in net.path_switches(net.path(a, b)):
            tabs[s.name].add_rule({"dst_ip": b.ip}, "fwd"); dup += 1
tot_c = sum(t.size() for t in tabs.values())

rate = net.iperf([net.hosts[0], net.hosts[-1]])
c = Counter("pkts", 8)
for i in range(1000): c.increment(i % 8, 1500)
acc = c.total_packets() / 1000
lat = 0.5 * 3
mc = sum(len(g["ports"]) for g in [{"ports":[1,2,3]},{"ports":[4,5,6]}])
print("hosts", [h.name for h in net.hosts], [h.ip for h in net.hosts])
print("path h1->h4", net.path("h1","h4"), "switches", len(net.path_switches(net.path("h1","h4"))))
print("A all-hosts-per-switch =", entries_all, " B skip-local =", tot_b,
      " C path-dedup =", tot_c, " C path-with-dups =", dup)
print("P4_TABLE_ENTRIES: %d" % entries_all)
print("P4_FORWARDING_RATE: %.2f" % rate)
print("P4_COUNTER_ACCURACY: %.2f" % acc, "bytes", c.total_bytes())
print("P4_PIPELINE_LATENCY: %.2f" % lat, "sw pipeline prop w/1 table:", net.switches[0].pipeline_latency_us)
print("P4_MULTICAST_GROUPS: %d" % mc)
EOF
